// Fragment shader, simplified: one sphere, one light, four tones.
// fbm() and rotate() are small helpers defined above the main function.
precision highp float;
uniform vec2 uResolution;
uniform float uYaw;
uniform float uTilt;
uniform float uCell;

const mat4 BAYER = mat4(
   0.0,  8.0,  2.0, 10.0,
  12.0,  4.0, 14.0,  6.0,
   3.0, 11.0,  1.0,  9.0,
  15.0,  7.0, 13.0,  5.0) / 16.0;

float land(vec3 p) {
  return smoothstep(0.48, 0.52, fbm(p * 2.4 + vec3(8.0, 3.0, 0.0)));
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * uResolution) / (0.5 * uResolution.y);
  float d2 = dot(uv, uv);
  if (d2 > 1.0) { discard; }

  vec3 n = rotate(vec3(uv, sqrt(1.0 - d2)), uYaw, uTilt);
  float light = max(dot(n, normalize(vec3(-0.45, 0.55, 0.7))), 0.0);
  float tone = mix(0.2, 1.0, light) * mix(0.35, 1.0, land(n));

  ivec2 cell = ivec2(mod(floor(gl_FragCoord.xy / uCell), 4.0));
  gl_FragColor = vec4(vec3(step(BAYER[cell.x][cell.y], tone)), 1.0);
}

import { createGlobe } from "pixel-globe";

const globe = createGlobe(document.querySelector("canvas")!, {
  cell: 6, // size of one "pixel", in CSS pixels
  tones: 4,
  accent: "#38d4f5",
});

globe.markers.add({ id: "paris", lat: 48.86, lon: 2.35, accent: true });
globe.rotateTo({ lat: 48.86, lon: 2.35 }, { duration: 900 });

// Everything is a plain function of time: pause it and nothing moves.
globe.pause();

export function diffStops(before: StopTime[], after: StopTime[]): StopChange[] {
  const index = new Map(before.map((s) => [`${s.trainId}:${s.stopSequence}`, s] as const));
  const changes: StopChange[] = [];

  for (const next of after) {
    const key = `${next.trainId}:${next.stopSequence}`;
    const prev = index.get(key);
    if (!prev) { changes.push({ kind: "added", stop: next }); continue; }
    if (prev.departure !== next.departure) changes.push({ kind: "retimed", stop: next, shiftMinutes: minutes(next.departure) - minutes(prev.departure) });
    index.delete(key);
  }

  for (const gone of index.values()) changes.push({ kind: "removed", stop: gone });
  return changes;
}

pub fn place(labels: &mut [Label], grid: &mut Grid, zoom: f32) -> usize {
    labels.sort_by(|a, b| b.priority.total_cmp(&a.priority));
    let mut placed = 0;

    for label in labels.iter_mut() {
        label.state = State::Hidden;
        for candidate in label.candidates(zoom) {
            if grid.is_free(&candidate.rect) {
                grid.insert(label.id, candidate.rect);
                label.anchor = candidate;
                label.state = State::Visible;
                placed += 1;
                break;
            }
        }
    }
    placed
}
